arguments.sql_query:
SELECT concept_id, concept_name, vocabulary_id, concept_code FROM omop.concept WHERE domain_id='Condition' AND standard_concept='S' AND LOWER(concept_name) IN (
'disorder of respiratory system','respiratory disease','disorder of circulatory system','disorder of cardiovascular system','disorder of endocrine system','metabolic disease','disorder of digestive system','disorder of nervous system','mental disorder','disorder of musculoskeletal system','disorder of urinary system','infectious disease','injury','neoplasm','disorder of kidney','renal disease','diabetes mellitus','hypertensive disorder','disorder of hematopoietic structure','disorder of immune function'
) ORDER BY concept_name;
